#!/usr/bin/env node
/**
 * Replaces the Trail TST demo GPX in Supabase Storage (bucket `race-gpx`) with the files generated by
 * `generate-trail-tst-gpx.mjs`, then updates `races.gpx_sha256` / `gpx_hash`.
 *
 * Races are matched by the sha256 of the OLD 13-point demo files, so only rows that still carry those exact
 * files are touched (seed rows and the organizer copies of the daily-refreshed demo edition). Every
 * current object is downloaded to `--backup-dir` before it is overwritten.
 *
 * Production write: run it only with the maintainer's go.
 *   SUPABASE_URL=… SUPABASE_SERVICE_ROLE_KEY=… node scripts/demo-gpx/upload-trail-tst-gpx.mjs --backup-dir <dir> [--dry-run]
 */
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const OLD_SHA_TO_FILE = {
  "653eadfbce0250664bd60c863e740183aa9d2dd8a7b64e107b38f4280fd3b038": "trail-tst-18.gpx",
  "33821e16a981ebd7e0fd580e3c55beef5164fa0f180afa97b8409c9034d51f94": "trail-tst-42.gpx",
  "4f9724285840219fd6613c231b901e3e09fa4cd8a99d587024fc88eca4abd762": "trail-tst-82.gpx",
};
const ASSETS_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "supabase", "demo-assets");

const args = process.argv.slice(2);
const dryRun = args.includes("--dry-run");
const backupIndex = args.indexOf("--backup-dir");
const backupDir = backupIndex >= 0 ? args[backupIndex + 1] : null;
const url = process.env.SUPABASE_URL?.replace(/\/$/, "");
const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!url || !key) throw new Error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required.");
if (!backupDir) throw new Error("--backup-dir <dir> is required (current objects are saved there first).");

const headers = { apikey: key, Authorization: `Bearer ${key}` };
const shaList = Object.keys(OLD_SHA_TO_FILE).join(",");
const racesResponse = await fetch(`${url}/rest/v1/races?gpx_sha256=in.(${shaList})&select=id,name,gpx_storage_path,gpx_sha256`, { headers });
if (!racesResponse.ok) throw new Error(`races lookup failed: ${racesResponse.status} ${await racesResponse.text()}`);
const races = await racesResponse.json();
console.log(`${races.length} race(s) still use the old demo GPX.`);

mkdirSync(backupDir, { recursive: true });
for (const race of races) {
  const file = OLD_SHA_TO_FILE[race.gpx_sha256];
  const content = readFileSync(join(ASSETS_DIR, file), "utf8");
  const sha = createHash("sha256").update(content).digest("hex");
  const objectUrl = `${url}/storage/v1/object/race-gpx/${race.gpx_storage_path}`;
  console.log(`- ${race.name} (${race.id}) ${race.gpx_storage_path} -> ${file} ${sha}`);
  if (dryRun) continue;

  const current = await fetch(objectUrl, { headers });
  if (!current.ok) throw new Error(`backup download failed for ${race.id}: ${current.status}`);
  writeFileSync(join(backupDir, `${race.id}.gpx`), await current.text(), "utf8");

  const upload = await fetch(objectUrl, {
    method: "PUT",
    headers: { ...headers, "Content-Type": "application/gpx+xml", "x-upsert": "true" },
    body: content,
  });
  if (!upload.ok) throw new Error(`upload failed for ${race.id}: ${upload.status} ${await upload.text()}`);

  const update = await fetch(`${url}/rest/v1/races?id=eq.${race.id}`, {
    method: "PATCH",
    headers: { ...headers, "Content-Type": "application/json", Prefer: "return=minimal" },
    body: JSON.stringify({ gpx_sha256: sha, gpx_hash: sha }),
  });
  if (!update.ok) throw new Error(`sha update failed for ${race.id}: ${update.status} ${await update.text()}`);
}
console.log(dryRun ? "Dry run: nothing written." : `Done. Backups in ${backupDir}.`);
